import { LARGE_PASTE_THRESHOLD } from "./constants";
import type {
  FinalTextStats,
  ProvenanceKind,
  ProvenanceSummary,
  SessionStats,
} from "./types";

/**
 * Pure function: derive ratios from raw stats. No side effects.
 * When there is no typed/pasted input at all, typingRatio defaults to 1
 * (treated as "nothing to be suspicious about yet" — the classifier
 * still returns "Unverified" on an empty session via totalChars === 0).
 */
export function summarize(stats: SessionStats): ProvenanceSummary {
  const inputTotal = stats.typedChars + stats.pastedChars;
  const typingRatio = inputTotal === 0 ? 1 : stats.typedChars / inputTotal;
  const pastedRatio = inputTotal === 0 ? 0 : stats.pastedChars / inputTotal;
  return {
    typingRatio,
    pastedRatio,
    hasLargePaste: stats.largePasteEvents > 0,
  };
}

export function computeFinalTextStats(
  kinds: readonly ProvenanceKind[],
): FinalTextStats {
  let typedChars = 0;
  let pastedChars = 0;
  let unknownChars = 0;

  for (const kind of kinds) {
    if (kind === "typed") typedChars += 1;
    else if (kind === "pasted") pastedChars += 1;
    else unknownChars += 1;
  }

  const totalChars = kinds.length;

  return {
    typedChars,
    pastedChars,
    unknownChars,
    totalChars,
    typingRatio: totalChars === 0 ? 0 : typedChars / totalChars,
    pastedRatio: totalChars === 0 ? 0 : pastedChars / totalChars,
  };
}

export function summarizeFinalText(
  finalTextStats: FinalTextStats,
  kinds: readonly ProvenanceKind[],
): ProvenanceSummary {
  return {
    typingRatio: finalTextStats.typingRatio,
    pastedRatio: finalTextStats.pastedRatio,
    hasLargePaste: hasLargePastedRun(kinds),
  };
}

export function hasLargePastedRun(
  kinds: readonly ProvenanceKind[],
  threshold = LARGE_PASTE_THRESHOLD,
): boolean {
  let run = 0;

  for (const kind of kinds) {
    if (kind === "pasted") {
      run += 1;
      if (run >= threshold) return true;
    } else {
      run = 0;
    }
  }

  return false;
}
